<?php require_once __DIR__.'/includes/functions.php'; $slug=trim($_GET['slug']??'');$s=$pdo->prepare("SELECT a.*,c.name category_name,c.slug category_slug FROM articles a JOIN categories c ON c.id=a.category_id WHERE a.slug=? AND a.status='published'");$s->execute([$slug]);$a=$s->fetch();if(!$a){http_response_code(404);exit('Article not found');}$page_title=$a['title'];$page_desc=$a['excerpt'];$canonical=article_url($a['slug']);require __DIR__.'/includes/header.php'; ?><article class="article"><a class="category" href="<?=base_url('category.php?slug='.rawurlencode($a['category_slug']))?>"><?=e($a['category_name'])?></a><h1><?=e($a['title'])?></h1><div class="meta">Published <?=e(date('F d, Y',strtotime($a['published_at'])))?></div><?php render_ad('top'); ?><div class="content"><?= $a['content_html'] ?></div><?php render_ad('inarticle'); ?><div class="share-note">Enjoyed this article? Explore more resources from INFOROVA.</div><?php render_ad('bottom'); ?></article><?php require __DIR__.'/includes/footer.php'; ?>
